import { Command } from 'commander';

export type SupportedShell = 'bash' | 'zsh' | 'fish';

/**
 * Generates Bash autocompletion script for the Stellar Alerts CLI.
 */
export function generateBashCompletion(cliName: string = 'stellar-alerts-cli'): string {
  return `#!/usr/bin/env bash
# Bash completion for \${cliName}
# Generated by '\${cliName} completion bash'

_\${cliName//-/_}_completions() {
  local cur prev words cword
  if type _init_completion >/dev/null 2>&1; then
    _init_completion || return
  else
    COMPREPLY=()
    cur="\${COMP_WORDS[COMP_CWORD]}"
    prev="\${COMP_WORDS[COMP_CWORD-1]}"
    words=("\${COMP_WORDS[@]}")
    cword=\$COMP_CWORD
  fi

  local root_commands="wallet stream profile health completion"
  local global_opts="--api-url -u --profile --help -h --version -V"

  case "\${prev}" in
    wallet)
      COMPREPLY=( $(compgen -W "list add remove update import export" -- "\${cur}") )
      return 0
      ;;
    stream)
      COMPREPLY=( $(compgen -W "start stop status events" -- "\${cur}") )
      return 0
      ;;
    profile)
      COMPREPLY=( $(compgen -W "list create use show delete export" -- "\${cur}") )
      return 0
      ;;
    completion)
      COMPREPLY=( $(compgen -W "bash zsh fish" -- "\${cur}") )
      return 0
      ;;
    --profile)
      return 0
      ;;
    --api-url|-u)
      return 0
      ;;
  esac

  if [[ "\${cur}" == -* ]]; then
    COMPREPLY=( $(compgen -W "\${global_opts}" -- "\${cur}") )
    return 0
  fi

  COMPREPLY=( $(compgen -W "\${root_commands}" -- "\${cur}") )
  return 0
}

complete -F _\${cliName//-/_}_completions \${cliName}
`;
}

/**
 * Generates Zsh autocompletion script for the Stellar Alerts CLI.
 */
export function generateZshCompletion(cliName: string = 'stellar-alerts-cli'): string {
  return `#compdef \${cliName}
# Zsh completion for \${cliName}
# Generated by '\${cliName} completion zsh'

_\${cliName//-/_}() {
  local -a commands
  local -a global_opts

  global_opts=(
    '(-u --api-url)'{-u,--api-url}'[API base URL]:url:'
    '--profile[Configuration profile to use]:profile:'
    '(-h --help)'{-h,--help}'[Display help for command]'
    '(-V --version)'{-V,--version}'[Output the version number]'
  )

  _arguments -C \
    "\${global_opts[@]}" \
    '1: :->command' \
    '*:: :->args'

  case \$state in
    command)
      commands=(
        'wallet:Manage monitored wallets'
        'stream:Control and inspect event streams'
        'profile:Manage named configuration profiles'
        'health:Check API health status'
        'completion:Generate shell autocompletion script'
      )
      _describe -t commands 'command' commands
      ;;
    args)
      case \$line[1] in
        wallet)
          local -a wallet_cmds
          wallet_cmds=(
            'list:List monitored wallets'
            'add:Add a new wallet to monitoring'
            'remove:Remove a wallet from monitoring'
            'update:Update wallet monitoring settings'
          )
          _describe -t wallet_cmds 'wallet command' wallet_cmds
          ;;
        stream)
          local -a stream_cmds
          stream_cmds=(
            'start:Start an event ingestion stream'
            'stop:Stop an active stream'
            'status:Check stream health and cursor'
            'events:Tail recent stream events'
          )
          _describe -t stream_cmds 'stream command' stream_cmds
          ;;
        profile)
          local -a profile_cmds
          profile_cmds=(
            'list:List all configured profiles'
            'create:Create a new configuration profile'
            'use:Set active profile'
            'show:Show current profile details'
            'delete:Remove a profile'
          )
          _describe -t profile_cmds 'profile command' profile_cmds
          ;;
        completion)
          local -a shells
          shells=('bash:Generate Bash completion script' 'zsh:Generate Zsh completion script' 'fish:Generate Fish completion script')
          _describe -t shells 'shell' shells
          ;;
      esac
      ;;
  esac
}

_\${cliName//-/_} "\$@"
`;
}

/**
 * Generates Fish autocompletion script for the Stellar Alerts CLI.
 */
export function generateFishCompletion(cliName: string = 'stellar-alerts-cli'): string {
  return `# Fish completion for \${cliName}
# Generated by '\${cliName} completion fish'

complete -c \${cliName} -f

# Global options
complete -c \${cliName} -s u -l api-url -d 'API base URL' -r
complete -c \${cliName} -l profile -d 'Configuration profile to use' -r
complete -c \${cliName} -s h -l help -d 'Display help for command'
complete -c \${cliName} -s V -l version -d 'Output the version number'

# Root commands
complete -c \${cliName} -n "__fish_use_subcommand" -a wallet -d 'Manage monitored wallets'
complete -c \${cliName} -n "__fish_use_subcommand" -a stream -d 'Control and inspect event streams'
complete -c \${cliName} -n "__fish_use_subcommand" -a profile -d 'Manage named configuration profiles'
complete -c \${cliName} -n "__fish_use_subcommand" -a health -d 'Check API health status'
complete -c \${cliName} -n "__fish_use_subcommand" -a completion -d 'Generate shell autocompletion script'

# Wallet subcommands
complete -c \${cliName} -n "__fish_seen_subcommand_from wallet" -a list -d 'List monitored wallets'
complete -c \${cliName} -n "__fish_seen_subcommand_from wallet" -a add -d 'Add a new wallet'
complete -c \${cliName} -n "__fish_seen_subcommand_from wallet" -a remove -d 'Remove a wallet'
complete -c \${cliName} -n "__fish_seen_subcommand_from wallet" -a update -d 'Update wallet settings'

# Stream subcommands
complete -c \${cliName} -n "__fish_seen_subcommand_from stream" -a start -d 'Start event stream'
complete -c \${cliName} -n "__fish_seen_subcommand_from stream" -a stop -d 'Stop event stream'
complete -c \${cliName} -n "__fish_seen_subcommand_from stream" -a status -d 'Stream status'
complete -c \${cliName} -n "__fish_seen_subcommand_from stream" -a events -d 'Tail stream events'

# Profile subcommands
complete -c \${cliName} -n "__fish_seen_subcommand_from profile" -a list -d 'List profiles'
complete -c \${cliName} -n "__fish_seen_subcommand_from profile" -a create -d 'Create profile'
complete -c \${cliName} -n "__fish_seen_subcommand_from profile" -a use -d 'Switch active profile'
complete -c \${cliName} -n "__fish_seen_subcommand_from profile" -a show -d 'Show active profile'
complete -c \${cliName} -n "__fish_seen_subcommand_from profile" -a delete -d 'Delete profile'

# Completion options
complete -c \${cliName} -n "__fish_seen_subcommand_from completion" -a "bash zsh fish"
`;
}

/**
 * Registers the 'completion' command on the Commander root program.
 */
export function registerCompletionCommands(program: Command): void {
  program
    .command('completion [shell]')
    .description('Generate shell auto-completion script for Bash, Zsh, or Fish')
    .addHelpText(
      'after',
      `
Installation Instructions:
  Bash:
    $ eval "$(stellar-alerts-cli completion bash)"
    Or persist to system profile:
    $ stellar-alerts-cli completion bash > /etc/bash_completion.d/stellar-alerts-cli

  Zsh:
    $ stellar-alerts-cli completion zsh > ~/.zsh/completion/_stellar-alerts-cli
    Ensure ~/.zsh/completion is in your $fpath in ~/.zshrc:
    fpath=(~/.zsh/completion $fpath)
    autoload -Uz compinit && compinit

  Fish:
    $ stellar-alerts-cli completion fish > ~/.config/fish/completions/stellar-alerts-cli.fish
`,
    )
    .action((shell?: string) => {
      const targetShell = (shell || 'bash').toLowerCase() as SupportedShell;
      switch (targetShell) {
        case 'bash':
          process.stdout.write(generateBashCompletion(program.name()));
          break;
        case 'zsh':
          process.stdout.write(generateZshCompletion(program.name()));
          break;
        case 'fish':
          process.stdout.write(generateFishCompletion(program.name()));
          break;
        default:
          console.error(
            `Unsupported shell: '\${shell}'. Supported shells: bash, zsh, fish`,
          );
          process.exit(1);
      }
    });
}
